package com.gerenciadorrural.modules.herd.application;
import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.shared.tenancy.*; import java.util.Objects; import org.springframework.stereotype.Service;
@Service public class ListCurrentFarmAnimals { private final TenantTransactionExecutor transactions; private final HerdAnimalQueryRepository repository; public ListCurrentFarmAnimals(TenantTransactionExecutor transactions,HerdAnimalQueryRepository repository){this.transactions=transactions;this.repository=repository;} public HerdAnimalPage execute(TenantContext context,HerdAnimalQuery query){Objects.requireNonNull(context,"O contexto de tenant é obrigatório");Objects.requireNonNull(query,"A consulta é obrigatória");return transactions.execute(context,()->repository.list(context.tenantId(),context.farmId(),query));} }
